import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { updateAcademyTracksAsync } from '../../../store/contentSlice';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import Modal from '../../../components/ui/Modal';
import { useToast } from '../../../contexts/ToastContext';
import ConfirmationModal from '../../../components/ui/ConfirmationModal';

const AcademyTracksManagement = () => {
    const dispatch = useDispatch();
    const { addToast } = useToast();
    const tracks = useSelector((state) => state.content.academyTracks) || [];
    const courses = useSelector((state) => state.content.academy) || [];
    
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingTrack, setEditingTrack] = useState(null);
    const [formData, setFormData] = useState({
        id: '',
        title: '',
        description: '',
        price: 0,
        courses: []
    });
    
    const [deleteId, setDeleteId] = useState(null);
    const [isDeleting, setIsDeleting] = useState(false);
    
    const handleOpenModal = (track = null) => {
        if (track) {
            setEditingTrack(track);
            setFormData(track);
        } else {
            setEditingTrack(null);
            setFormData({
                id: `track-${Date.now()}`,
                title: '',
                description: '',
                price: 0,
                courses: []
            });
        }
        setIsModalOpen(true);
    };

    const handleCourseToggle = (courseId) => {
        const currentCourses = formData.courses || [];
        if (currentCourses.includes(courseId)) {
            setFormData({ ...formData, courses: currentCourses.filter(id => id !== courseId) });
        } else {
            setFormData({ ...formData, courses: [...currentCourses, courseId] });
        }
    };

    const handleSaveTrack = async (e) => {
        e.preventDefault();
        
        if (!formData.title.trim()) {
            addToast("Track title is required", "error");
            return;
        }

        let updatedTracks;
        if (editingTrack) {
            updatedTracks = tracks.map(t => t.id === formData.id ? formData : t);
        } else {
            updatedTracks = [...tracks, formData];
        }

        try {
            await dispatch(updateAcademyTracksAsync(updatedTracks)).unwrap();
            addToast(`Track ${editingTrack ? 'updated' : 'created'} successfully!`, 'success');
            setIsModalOpen(false);
        } catch (error) {
            console.error('Failed to save track:', error);
            addToast('Failed to save track', 'error');
        }
    };

    const performDelete = async () => {
        if (!deleteId) return;
        setIsDeleting(true);
        try {
            const updatedTracks = tracks.filter(t => String(t.id) !== String(deleteId));
            await dispatch(updateAcademyTracksAsync(updatedTracks)).unwrap();
            addToast('Track deleted successfully', 'success');
        } catch (error) {
            addToast(`Failed to delete track: ${error}`, 'error');
        } finally {
            setIsDeleting(false);
            setDeleteId(null);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-xl font-bold flex items-center gap-2">
                        <Icon name="Layers" size={24} className="text-secondary" />
                        Tracks Management
                    </h2>
                    <p className="text-sm text-muted-foreground mt-1">Bundle multiple courses into a single track with an overarching price.</p>
                </div>
                <Button onClick={() => handleOpenModal()} className="gap-2 shrink-0">
                    <Icon name="Plus" size={16} />
                    Create Track
                </Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {tracks.map((track) => (
                    <div key={track.id} className="bg-card border border-border rounded-2xl p-6 shadow-sm flex flex-col">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <h3 className="font-bold text-lg mb-1">{track.title}</h3>
                                <p className="text-sm text-muted-foreground line-clamp-2">{track.description}</p>
                            </div>
                            <div className="text-right ml-4 shrink-0">
                                <span className="block text-xs uppercase font-bold text-muted-foreground">Price</span>
                                <span className="text-lg font-black text-success">
                                    {Number(track.price) === 0 ? 'FREE' : `₦${Number(track.price).toLocaleString()}`}
                                </span>
                            </div>
                        </div>
                        
                        <div className="mb-6 flex-1">
                            <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-2 block">Included Courses</span>
                            {track.courses && track.courses.length > 0 ? (
                                <ul className="space-y-2">
                                    {track.courses.map(courseId => {
                                        const c = courses.find(c => c.id === courseId);
                                        return (
                                            <li key={courseId} className="text-sm flex items-center gap-2 text-primary">
                                                <Icon name="CheckCircle2" size={14} className="text-secondary" />
                                                <span className="line-clamp-1">{c ? c.title : `Unknown Course (${courseId})`}</span>
                                            </li>
                                        );
                                    })}
                                </ul>
                            ) : (
                                <p className="text-sm text-muted-foreground italic">No courses added yet.</p>
                            )}
                        </div>

                        <div className="grid grid-cols-2 gap-2 pt-4 border-t border-border mt-auto">
                            <Button variant="outline" onClick={() => handleOpenModal(track)} className="w-full text-xs">
                                Edit Track
                            </Button>
                            <Button variant="outline" className="w-full text-xs text-red-500 border-red-500/20 hover:bg-red-500/10" onClick={() => setDeleteId(track.id)}>
                                Delete Track
                            </Button>
                        </div>
                    </div>
                ))}
            </div>

            <Modal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                title={editingTrack ? "Edit Track" : "Create New Track"}
                size="lg"
            >
                <form onSubmit={handleSaveTrack} className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Track Title</label>
                            <input
                                type="text"
                                value={formData.title}
                                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                                className="w-full px-4 py-2 bg-background border border-border rounded-xl"
                                placeholder="e.g., Digital Creator - Elite"
                                required
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Overarching Price (₦)</label>
                            <input
                                type="number"
                                value={formData.price}
                                onChange={(e) => setFormData({ ...formData, price: Number(e.target.value) })}
                                className="w-full px-4 py-2 bg-background border border-border rounded-xl"
                                min="0"
                                required
                            />
                        </div>
                    </div>
                    
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Description</label>
                        <textarea
                            value={formData.description}
                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                            className="w-full px-4 py-2 bg-background border border-border rounded-xl min-h-[80px]"
                            placeholder="Brief description of this track"
                        />
                    </div>

                    <div className="space-y-3">
                        <label className="text-sm font-medium flex justify-between items-center">
                            <span>Select Courses for this Track</span>
                            <span className="text-xs font-bold text-muted-foreground bg-muted px-2 py-1 rounded-full">
                                {(formData.courses || []).length} Selected
                            </span>
                        </label>
                        <div className="border border-border rounded-xl p-4 max-h-[300px] overflow-y-auto bg-muted/20 space-y-2">
                            {courses.map(course => (
                                <label key={course.id} className="flex items-start gap-3 p-3 border border-border/50 rounded-lg hover:bg-muted/50 cursor-pointer transition-colors">
                                    <input
                                        type="checkbox"
                                        checked={(formData.courses || []).includes(course.id)}
                                        onChange={() => handleCourseToggle(course.id)}
                                        className="mt-1"
                                    />
                                    <div>
                                        <div className="font-bold text-sm text-primary">{course.title}</div>
                                        <div className="text-xs text-muted-foreground">{course.category}</div>
                                    </div>
                                </label>
                            ))}
                        </div>
                    </div>

                    <div className="flex justify-end gap-3 pt-6 border-t border-border">
                        <Button type="button" variant="ghost" onClick={() => setIsModalOpen(false)}>
                            Cancel
                        </Button>
                        <Button type="submit">
                            {editingTrack ? 'Save Changes' : 'Create Track'}
                        </Button>
                    </div>
                </form>
            </Modal>

            <ConfirmationModal
                isOpen={!!deleteId}
                onClose={() => setDeleteId(null)}
                onConfirm={performDelete}
                title="Delete Track?"
                message="Are you sure you want to delete this track? This will not delete the underlying courses, only the track bundle itself."
                confirmText={isDeleting ? "Deleting..." : "Delete Track"}
                isDestructive={true}
                isLoading={isDeleting}
            />
        </div>
    );
};

export default AcademyTracksManagement;
